def main():
    import sys
    input = sys.stdin.read
    data = input().splitlines()

    n = int(data[0])
    queries = data[1:n+1]

    memo = {}

    def get_earliest_year(s):
        if s in memo:
            return memo[s]
        m = len(s)
        lower = 1989
        y_num = int(s)
        mod = 10 ** m
        current = lower
        last_part = current % mod
        if last_part == y_num:
            Y_candidate = current
        else:
            delta = y_num - last_part
            if delta < 0:
                delta += mod
            Y_candidate = current + delta

        while True:
            valid = True
            for k in range(1, m):
                k_suffix_num = Y_candidate % (10 ** k)
                s_k = str(k_suffix_num).zfill(k)
                if s_k not in memo:
                    e = get_earliest_year(s_k)
                    memo[s_k] = e
                else:
                    e = memo[s_k]
                if e >= Y_candidate:
                    valid = False
                    break
            if valid:
                memo[s] = Y_candidate
                return Y_candidate
            else:
                Y_candidate += mod

    for q in queries:
        abbr = q
        suffix = abbr.split("'")[1]
        year = get_earliest_year(suffix)
        print(year)

main()

