import sys
from functools import lru_cache

def largest_cube_root(m):
    if m == 0:
        return 0
    low = 1
    high = 1
    while high ** 3 <= m:
        high *= 2
    while low < high:
        mid = (low + high + 1) // 2
        if mid ** 3 <= m:
            low = mid
        else:
            high = mid - 1
    return low

@lru_cache(maxsize=None)
def solve(m):
    if m == 0:
        return (0, 0)
    a = largest_cube_root(m)
    # Option 1: take a^3
    block1, x1 = solve(m - a**3)
    option1 = (block1 + 1, a**3 + x1)
    # Option 2: take (a-1)^3 and recurse on m - (a-1)^3
    if a > 1:
        block2, x2 = solve(m - (a-1)**3)
        option2 = (block2 + 1, (a-1)**3 + x2)
    else:
        option2 = (0, 0)
    if option1[0] > option2[0]:
        return option1
    elif option1[0] < option2[0]:
        return option2
    else:
        # Choose the one with higher X
        if option1[1] > option2[1]:
            return option1
        else:
            return option2

def main():
    m = int(sys.stdin.readline())
    blocks, x = solve(m)
    print(blocks, x)

