import string

def solve():
    n, m, a, b, c = map(int, sys.stdin.readline().split())
    total_area = n * m
    required_area = 0
    used_a = 0
    used_b = 0
    used_c = 0

    if n % 2 == 0 and m % 2 == 0:
        required_area = (n // 2) * (m // 2)
        if c >= required_area:
            used_c = required_area
            c -= required_area
            required_area = 0
        else:
            required_area -= c
            used_c = c
            required_area = (n // 2) * (m // 2) - c

    else:
        required_area = (n * m + 1) // 2
        if n % 2 == 1:
            required_area -= (n // 2) * (m // 2)
        else:
            required_area -= (m // 2) * (n // 2)

    # We need to cover required_area with a and b
    # Each a or b covers 2 squares
    if (a + b) < required_area:
        print("IMPOSSIBLE")
        return

    # Fill the rest with a and b
    used_a = min(required_area, a)
    used_b = required_area - used_a
    used_b = min(used_b, b)

    # Create the grid
    grid = [['' for _ in range(m)] for _ in range(n)]
    letters = list(string.ascii_lowercase)

    # Fill with c planks (2x2)
    for i in range(0, n, 2):
        for j in range(0, m, 2):
            if c > 0:
