import sys
import heapq

def main():
    n = int(sys.stdin.readline())
    sizes = []
    for _ in range(n):
        k, a = map(int, sys.stdin.readline().split())
        heapq.heappush(sizes, (k, a))

    result = 0
    current = 0
    while sizes:
        k, a = heapq.heappop(sizes)
        if k > result:
            result = k
        else:
            current += a
        if current >= 4:
            current >>= 2
            result += 1
    print(result)

if __name__ == "__main__":
    main()

