import sys
sys.setrecursionlimit(1000000)

def find_route(n, stamps):
    from collections import defaultdict, deque

    graph = defaultdict(list)
    for u, v in stamps:
        graph[u].append(v)
        graph[v].append(u)

    visited = set()
    path = []

    def dfs(node, prev):
        visited.add(node)
        path.append(node)
        for neighbor in graph[node]:
            if neighbor != prev:
                dfs(neighbor, node)

    for start in graph:
        if start not in visited:
            dfs(start, -1)
            if len(path) == n + 1:
                return path
            path.clear()
    return []

def main():
    n = int(sys.stdin.readline())
    stamps = []
    for _ in range(n):
        a, b = map(int, sys.stdin.readline().split())
        stamps.append((a, b))
    route = find_route(n, stamps)
    print(' '.join(map(str, route)))

