    import sys
    input = sys.stdin.read
    data = input().split()
    s = data[0]
    t = data[1]
    dx = ord(t[0]) - ord(s[0])
    dy = int(t[1]) - int(s[1])
    path = []
    x, y = ord(s[0]) - ord('a'), int(s[1]) - 1
    tx, ty = ord(t[0]) - ord('a'), int(t[1]) - 1
    while x != tx or y != ty:
        if x < tx:
            if y < ty:
                path.append('RU')
            elif y > ty:
                path.append('RD')
            else:
                path.append('R')
        elif x > tx:
            if y < ty:
                path.append('LU')
            elif y > ty:
                path.append('LD')
            else:
                path.append('L')
        else:
            if y < ty:
                path.append('U')
            elif y > ty:
                path.append('D')
