def adjust_year(y):
    for i in range(4):
        for d in range(0, 10):
            if i == 0 and d == 0:
                continue
            new_y = y[:i] + str(d) + y[i+1:]
            if 1000 <= int(new_y) <= 2011:
                return int(new_y)
    return None

