def main():
    import sys
    input = sys.stdin.read
    data = input().split('\n')

    n, m, k = map(int, data[0].split())
    direction = data[1].strip()
    states = data[2].strip()

    # Controller's movement
    def move_controller(controller_pos, direction):
        if direction == 'to head':
            new_pos = controller_pos - 1
            if new_pos == 0:
                new_pos = n
                direction = 'to tail'
        else:  # to tail
            new_pos = controller_pos + 1
            if new_pos == n + 1:
                new_pos = 1
                direction = 'to head'
        return new_pos, direction

    # Stowaway's possible moves
    def stowaway_moves(pos, state):
        if state == '0':
            return [pos - 1, pos, pos + 1]
        else:
            return [pos]  # only stays in place

    # BFS for stowaway's optimal path
    visited = set()
    queue = deque()
    queue.append((m, 0, 0, direction))
    caught_time = -1

    while queue:
        stow_pos, time, state_idx, ctrl_dir = queue.popleft()
        if (stow_pos, ctrl_dir) in visited:
            continue
        visited.add((stow_pos, ctrl_dir))

        if time >= len(states):
            print("Stowaway")
            return

        current_state = states[state_idx]

        # Controller moves
        ctrl_pos = k
        if current_state == '0':
            ctrl_pos, ctrl_dir = move_controller(ctrl_pos, ctrl_dir)

        # Check if caught
        if stow_pos == ctrl_pos:
            caught_time = time + 1
            break

        # Stowaway moves
        next_states = []
        if current_state == '0':
            next_positions = stowaway_moves(stow_pos, current_state)
            for np in next_positions:
                if 1 <= np <= n:
                    next_states.append(np)
        else:
            next_states = [stow_pos]

        for np in next_states:
            new_state_idx = state_idx + 1
            queue.append((np, time + 1, new_state_idx, ctrl_dir))

    if caught_time != -1:
        print(f"Controller {caught_time}")
    else:
        print("Stowaway")

