    class K:
        def __init__(self, obj, *args):
            self.obj = obj
        def __lt__(self, other):
            return func(self.obj, other.obj) < 0
        def __gt__(self, other):
            return func(self.obj, other.obj) > 0
        def __eq__(self, other):
            return func(self.obj, other.obj) == 0
    return K

