# Determine the final position after n moves
# Each move is a swap: odd move swaps 0 and 1, even move swaps 1 and 2

# Since the pattern repeats every 2 moves, we can find the effective number of moves modulo 2
effective_moves = n % 2

# Define the swap operations
def swap_odd(pos):
    if pos == 0:
        return 1
    elif pos == 1:
        return 0
    else:
        return 2

def swap_even(pos):
    if pos == 1:
        return 2
    elif pos == 2:
        return 1
    else:
        return 0

# Apply the swaps in reverse order to find the initial position
pos = x
for i in range(effective_moves, 0, -1):
    if i % 2 == 1:
        pos = swap_odd(pos)
    else:
        pos = swap_even(pos)

print(pos)

