import bisect

def main():
    n = int(sys.stdin.readline())
    rings = []
    for _ in range(n):
        a, b, h = map(int, sys.stdin.readline().split())
        rings.append((a, b, h))

    rings.sort(key=lambda x: (x[1], -x[0]))

    dp = []
    max_height = 0
    for a, b, h in rings:
        idx = bisect.bisect_left(dp, a)
        if idx == 0:
            current_height = h
        else:
            current_height = dp[idx - 1] + h
        while idx < len(dp) and dp[idx] <= current_height:
            idx += 1
        if idx == 0:
            dp = [current_height]
        else:
            dp[idx - 1] = current_height
        max_height = max(max_height, current_height)

    print(max_height)

main()

