import sys
import collections

def main():
    sys.setrecursionlimit(1 << 25)
    n = int(sys.stdin.readline())
    tree = [[] for _ in range(n + 1)]
    for _ in range(n - 1):
        x, y = map(int, sys.stdin.readline().split())
        tree[x].append(y)
        tree[y].append(x)

    color = [0] * (n + 1)
    used_colors = set()
    queue = collections.deque()
    queue.append(1)
    color[1] = 1
    while queue:
        node = queue.popleft()
        for neighbor in tree[node]:
            if color[neighbor] == 0:
                color[neighbor] = color[node] + 1
                queue.append(neighbor)
            else:
                if color[neighbor] == color[node]:
                    used_colors.add(color[node])
                    used_colors.add(color[neighbor])
                    while color[node] in used_colors:
                        color[node] += 1
                    while color[neighbor] in used_colors:
                        color[neighbor] += 1
                else:
                    used_colors.add(color[node])
                    used_colors.add(color[neighbor])
    print(max(color))
    print(' '.join(map(str, color[1:n+1])))

if __name__ == "__main__":
    main()

