def main():
    import sys
    input = sys.stdin.read
    data = input().split()

    n = int(data[0])
    m = int(data[1])
    queries = data[2:]

    # Precompute factorials and inverse factorials for Poisson distribution
    max_fact = 10**6 + 5
    fact = [1] * (max_fact)
    for i in range(1, max_fact):
        fact[i] = fact[i-1] * i

    def poisson_prob(k, lambda_val):
        if k < 0:
            return 0.0
        return math.exp(-lambda_val) * (lambda_val ** k) / fact[k]

    def uniform_prob(k, a, b):
        if a <= k <= b:
            return 1.0 / (b - a + 1)
        return 0.0

    results = []

    for i in range(n):
        village_data = queries[i * m : (i + 1) * m]
        counts = [int(x) for x in village_data]

        # Try Poisson distribution
        best_poisson = None
        min_error_poisson = float('inf')
        for l in range(1, 1000):
            prob = 0.0
            for c in counts:
                prob += poisson_prob(c, l)
            error = abs(prob - 1.0)
            if error < min_error_poisson:
                min_error_poisson = error
                best_poisson = l

        # Try Uniform distribution
        best_uniform = None
        min_error_uniform = float('inf')
        for a in range(1, 1000):
            for b in range(a, 1000):
                prob = 0.0
                for c in counts:
                    prob += uniform_prob(c, a, b)
                error = abs(prob - 1.0)
                if error < min_error_uniform:
                    min_error_uniform = error
                    best_uniform = (a, b)

        # Choose the best fit based on error
        if min_error_poisson < min_error_uniform:
            results.append(best_poisson)
        else:
            results.append((best_uniform[0] + best_uniform[1]) // 2)

    print('\n'.join(map(str, results)))

